import{_ as l,o as t,c as i,ai as _}from"./chunks/framework.ETupdKIa.js";const u=JSON.parse('{"title":"スマホ新法","description":"","frontmatter":{"title":"スマホ新法","date":"2026-01-12T00:00:00.000Z","status":"published"},"headers":[],"relativePath":"til/法律/20260112_スマホ新法.md","filePath":"til/法律/20260112_スマホ新法.md"}'),a={name:"til/法律/20260112_スマホ新法.md"};function p(o,e,r,s,n,d){return t(),i("div",null,[...e[0]||(e[0]=[_('<h1 id="_20260112-スマホ新法" tabindex="-1">20260112_スマホ新法 <a class="header-anchor" href="#_20260112-スマホ新法" aria-label="Permalink to “20260112_スマホ新法”">​</a></h1><p>2025/12/18(木)に、スマホ新法(スマートフォンにおいて利用される特定ソフトウェアに係る競争の促進に関する法律)が全面施行された。</p><p>これまで、スマホを利用する上で特に重要となる4つのソフトウェア、すなわち、OS、アプリストア、ブラウザ、検索エンジンについて、ビッグテックの寡占状態が続いてきたが、そこに競争原理を導入するために、公正取引委員会によって前述の法が制定・施行されることになった。</p><p>2025/12/18時点で規制の対象となる企業は、Apple、ITunes、Googleの3社で、前述の4つのソフトウェアを提供する際に複数の規制が導入される。</p><p>例</p><ul><li>アプリ外課金の許容 <ul><li>これまで、Apple、Googleともに、アプリ内での購入は、各社の決済システムを使用したアプリ内課金のみを認め、サードパーティー製の決済システムの利用や、アプリ外(主にWeb)へ誘導し課金させることを禁じていた。</li><li>スマホ新法によって、これまで禁止されていたサードパーティー製決済システムや、アプリ外への誘導が認められるようになり、これらを利用する場合は、アプリ内課金に比べてAppleへ支払う手数料が少なくなるため、アプリ事業者の収益に好影響を与えると言われている。</li></ul></li><li>サードパーティー製アプリストアの許容 <ul><li>Appleは、App Store以外でiPhone向けアプリを提供することを禁じていたが、それが解禁される。</li><li>Googleはこれまでも認めていたらしい。</li></ul></li><li>ブラウザ、検索エンジンのチョイス画面表示の義務化</li></ul>',6)])])}const m=l(a,[["render",p]]);export{u as __pageData,m as default};
